import{_ as e,o,c as t,a2 as d}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"O catálogo","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/catalog.md","filePath":"pt-BR/guide/catalog.md"}'),r={name:"pt-BR/guide/catalog.md"};function i(s,a,n,c,l,m){return o(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="o-catalogo" tabindex="-1">O catálogo <a class="header-anchor" href="#o-catalogo" aria-label="Permalink to &quot;O catálogo&quot;">​</a></h1><p><strong>Novo projeto → Catálogo</strong> lista aplicações que se instalam num passo: o Orbit cria o projeto, os bancos de dados de que a aplicação precisa com backups diários, e a própria aplicação, já configurada para usá-los. Cada entrada fixa uma versão de imagem, então o que você instala hoje é o que recebe, e o projeto oferece a atualização quando o catálogo avança.</p><h2 id="entries" tabindex="-1">O que tem nele <a class="header-anchor" href="#entries" aria-label="Permalink to &quot;O que tem nele {#entries}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entrada</th><th>O que é</th><th>Banco</th><th>Primeiro login</th></tr></thead><tbody><tr><td>n8n</td><td>Automação de fluxos</td><td>PostgreSQL</td><td>A primeira visita cria a conta do dono</td></tr><tr><td>Umami</td><td>Analytics de sites</td><td>PostgreSQL</td><td><code>admin</code> / <code>umami</code>, troque na hora</td></tr><tr><td>Metabase</td><td>Dashboards sobre seus bancos</td><td>PostgreSQL</td><td>Configuração na primeira visita</td></tr><tr><td>Grafana</td><td>Dashboards e alertas</td><td>PostgreSQL</td><td><code>admin</code> e a senha gerada</td></tr><tr><td>Directus</td><td>CMS headless e painel de administração</td><td>PostgreSQL</td><td>Seu email e a senha gerada</td></tr><tr><td>Wiki.js</td><td>Uma wiki</td><td>PostgreSQL</td><td>Configuração na primeira visita</td></tr><tr><td>Miniflux</td><td>Leitor de feeds</td><td>PostgreSQL</td><td><code>admin</code> e a senha gerada</td></tr><tr><td>Shlink</td><td>Encurtador de URLs</td><td>PostgreSQL</td><td>A chave de API gerada</td></tr><tr><td>linkding</td><td>Favoritos</td><td>PostgreSQL</td><td><code>admin</code> e a senha gerada</td></tr><tr><td>Vaultwarden</td><td>Servidor de senhas compatível com o Bitwarden</td><td>PostgreSQL</td><td>Crie sua conta na primeira visita; a página de admin usa o token gerado</td></tr><tr><td>IT-Tools</td><td>Ferramentas para desenvolvedores</td><td>nenhum</td><td>nada para configurar</td></tr></tbody></table><h2 id="install" tabindex="-1">O que a instalação faz <a class="header-anchor" href="#install" aria-label="Permalink to &quot;O que a instalação faz {#install}&quot;">​</a></h2><ol><li><strong>Revisão.</strong> A página da entrada lista o que o Orbit cria: a aplicação com imagem, porta, verificação de saúde e recursos, cada banco com tamanho e agenda de backup, e cada variável com a origem do valor. Os segredos são gerados no seu navegador; os que você precisa para entrar aparecem uma vez, com botão de copiar. Gere outros antes de instalar se preferir.</li><li><strong>Criação.</strong> O Orbit cria o projeto, depois os bancos, depois a aplicação, do mesmo jeito que o <a href="./compose">import de Compose</a>. As variáveis dos bancos são referências, resolvidas na hora do deploy, então trocar as credenciais de um banco depois continua funcionando.</li><li><strong>Endereço.</strong> Variáveis que precisam do endereço da própria aplicação, como <code>WEBHOOK_URL</code> ou <code>PUBLIC_URL</code>, não existem antes da aplicação. O Orbit define a partir do endereço gerado depois do primeiro deploy e faz o deploy de novo. Adicione seu próprio domínio depois em <strong>Domínios</strong> e atualize essas variáveis para ele.</li><li><strong>Email.</strong> n8n, Metabase, Grafana, Directus e Vaultwarden enviam email para convites, redefinição de senha e alertas. Com o Resend conectado e um domínio de envio verificado, um administrador pode deixar a instalação dar à aplicação o próprio <a href="./applications#email">email</a>: uma chave do Resend que só envia por aquele domínio, colocada nas variáveis que a aplicação lê, como <code>N8N_SMTP_HOST</code> e <code>N8N_EMAIL_MODE</code> no n8n ou <code>GF_SMTP_ENABLED</code> e <code>GF_SMTP_HOST</code> no Grafana, todas na porta 465 com TLS desde o início. Ela envia com o próprio nome no domínio de envio do Orbit; um domínio próprio pode substituir depois, pelas <strong>Variáveis</strong> dela.</li></ol><p>O resultado é um projeto comum: deploys, logs, variáveis, backups e o terminal funcionam como em qualquer outro.</p><h2 id="updates" tabindex="-1">Atualizações <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Atualizações {#updates}&quot;">​</a></h2><p>Um projeto lembra a entrada e a versão de onde veio. Quando o catálogo traz uma versão mais nova, a visão geral do projeto avisa e <strong>Revisar a atualização</strong> mostra o que mudaria: a tag nova da imagem e as variáveis que a entrada ganhou desde então, com a origem dos valores. Aplicar faz o deploy da imagem nova, adiciona as variáveis e registra a versão nova. Se a imagem da aplicação não vem mais do repositório da entrada, a imagem fica como está.</p><p>As entradas só avançam no catálogo que vem com o seu Orbit; <a href="./updates">atualizar o Orbit</a> traz o catálogo mais novo.</p><h2 id="not-yet" tabindex="-1">O que ainda não está nele <a class="header-anchor" href="#not-yet" aria-label="Permalink to &quot;O que ainda não está nele {#not-yet}&quot;">​</a></h2><p>Aplicações rodam sem volumes persistentes no Orbit, então o catálogo tem aplicações cujo estado cabe num banco gerenciado. Arquivos enviados ficam no contêiner e se perdem no próximo deploy, a menos que a aplicação consiga usar um <a href="./spaces">Space</a>. Isso deixa algumas populares de fora por enquanto:</p><ul><li><strong>Plausible</strong> precisa do ClickHouse, que o Orbit não gerencia.</li><li><strong>Uptime Kuma</strong> guarda os dados em SQLite num volume.</li><li><strong>Ghost</strong> guarda as imagens enviadas num volume.</li></ul>',13)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
